# Generated by manage.py generate_test_cases.
from typing import Any

from django.core.exceptions import PermissionDenied, ValidationError
from django.contrib.auth.models import AnonymousUser

from bloomerp.form_behaviors.builtins.add_filter import ADD_FILTER
from bloomerp.form_behaviors.definition import BehaviorContext, BehaviorResult, FieldStateUpdate
from bloomerp.models.application_field import ApplicationField
from bloomerp.tests.base import (
    BehaviorActionScenario, BloomerpBehaviorActionTestCase, ExpectedBehaviorActionException,
)


class TestAddFilterAction(BloomerpBehaviorActionTestCase):
    """Verify draft-dependent restrictions and target eligibility."""

    action = ADD_FILTER
    create_foreign_models = True
    auto_create_customers = False

    def filters(self, value: Any) -> list[dict[str, Any]]:
        """Build a country-name predicate using a literal or draft reference."""
        return [{"connector": "AND", "conditions": [
            {"field_path": "name", "lookup_id": "equals", "value": value},
        ]}]

    def get_test_scenarios(self) -> list[BehaviorActionScenario]:
        """Cover reference resolution, removal, blank sources, and invalid configurations."""
        listener = self.get_application_field("first_name")
        target = self.get_application_field("country")
        scenarios = []
        for value in ("Belgium", "France", ""):
            expected = self.filters(value) if value else [{"connector": "OR", "conditions": []}]
            scenarios.append(BehaviorActionScenario(
                name=f"Filter country choices for draft value {value!r}",
                context=BehaviorContext(
                    values={"first_name": value, "country": "existing-selection"},
                    listener_field="first_name", target_field="country",
                ),
                listener=listener, target=target,
                config={"filters": self.filters("{{ object.first_name }}")},
                expected_result=BehaviorResult(states=(FieldStateUpdate(field="country", choices_filter=expected),)),
            ))
        context = BehaviorContext(values={"first_name": "Belgium"}, listener_field="first_name", target_field="country")
        scenarios.append(BehaviorActionScenario(
            name="Empty filters remove the dynamic restriction", context=context,
            listener=listener, target=target, config={"filters": []},
            expected_result=BehaviorResult(states=(FieldStateUpdate(field="country", choices_filter=[]),)),
        ))
        for name, config, selected_target in (
            ("Reject scalar targets", {"filters": []}, listener),
            ("Reject reverse collection widgets", {"filters": []}, self.get_application_field("customers", self.CountryModel)),
            ("Reject unknown draft references", {"filters": self.filters("{{ object.missing }}")}, target),
            ("Reject row references", {"filters": self.filters("{{ row.name }}")}, target),
            ("Reject missing draft values", {"filters": self.filters("{{ object.last_name }}")}, target),
            ("Reject invalid filter structure", {"filters": [{"connector": "INVALID"}]}, target),
            ("Reject unknown lookup", {"filters": [{"connector": "AND", "conditions": [{"field_path": "name", "lookup_id": "missing", "value": "Belgium"}]}]}, target),
        ):
            scenarios.append(BehaviorActionScenario(
                name=name, context=context, listener=listener, target=selected_target,
                config=config, expected_exception=ExpectedBehaviorActionException(exception=ValidationError),
            ))
        return scenarios

    def test_only_foreign_picker_targets_are_offered(self) -> None:
        """Use case: Configure a behavior on a form containing mixed widgets.
        Expected result: Only supported relationship pickers appear as targets.
        """
        # 1. Obtain all customer fields, including scalar and relation widgets.
        fields = ApplicationField.get_for_model(self.CustomerModel)
        # 2. Confirm real foreign-key and user pickers are eligible but text is not.
        eligible = set(ADD_FILTER.get_target_fields(fields, self.get_application_field("first_name")).values_list("field", flat=True))
        self.assertTrue({"country", "customer_type", "user_account"} <= eligible)
        self.assertNotIn("first_name", eligible)

    def test_filter_permissions_are_required(self) -> None:
        """Use case: A user without policies requests a filter on related data.
        Expected result: Filter authorization rejects anonymous and unprivileged users.
        """
        # 1. Supply a valid relation restriction without granting related model access.
        context = BehaviorContext(values={"first_name": "Belgium"}, listener_field="first_name", target_field="country")
        # 2. Execute through the public action contract for both denied user classes.
        for user in (self.normal_user, AnonymousUser()):
            with self.subTest(user=str(user)), self.assertRaises(PermissionDenied):
                ADD_FILTER.run(context, {"filters": self.filters("Belgium")},
                    target=self.get_application_field("country"),
                    listener=self.get_application_field("first_name"), user=user)
